/**
 * A `compoundPath` draws several subpaths as a single path.
 * `shape.paths` is required and each subpath can be given either as a zrender
 * `Path` instance or as a path element option (like the other elements that
 * `renderItem` returns), which is normalized to a `Path` here.
 *
 * The normalized result is written back to `elOption.shape.paths`, because
 * `elOption.shape` is also applied on the element by the common shape updating
 * logic (see `applyUpdateTransition`).
 */
function normalizeCompoundPathShape(elOption: CustomCompoundPathOption): graphicUtil.Path[] {
    const shape = elOption.shape;

    if (!shape || !isArray(shape.paths)) {
        let errMsg = '';
        if (__DEV__) {
            errMsg = '"shape.paths" is required to be an array in the "compoundPath" element'
                + ' returned by `renderItem`.';
        }
        throwError(errMsg);
    }

    const paths = map(shape.paths, function (subPathOption) {
        if (isPath(subPathOption as Element)) {
            return subPathOption as graphicUtil.Path;
        }
        const subPathEl = createEl(subPathOption as CustomElementOption);
        if (!isPath(subPathEl)) {
            let errMsg = '';
            if (__DEV__) {
                errMsg = 'Only any type of `path` can be used in `shape.paths` of "compoundPath",'
                    + ' rather than ' + subPathEl.type + '.';
            }
            throwError(errMsg);
        }
        const subShape = (subPathOption as CustomBaseZRPathOption).shape;
        subShape && subPathEl.setShape(subShape);
        return subPathEl;
    });

    // Write back so that the subsequent common `shape` updating gets `Path` instances.
    shape.paths = paths;

    return paths;
}

