import { assert, defaults, isFunction, isString } from 'zrender/src/core/util';
import { EChartsExtensionInstallRegisters, EChartsExtensionInstaller, use } from '../../extension';
import CustomSeriesModel, { CustomSeriesOption, CustomSeriesRenderItem } from './CustomSeries';
import CustomChartView from './CustomView';

export function install(registers: EChartsExtensionInstallRegisters) {
    registers.registerChartView(CustomChartView);
    registers.registerSeriesModel(CustomSeriesModel);
}

/**
 * Create an installer of a reusable custom series, which brings a new series
 * type sharing the given `renderItem`. It can be installed by the standard
 * install flow, like the other charts:
 *
 * ```js
 * echarts.use(createCustomSeriesInstaller('myCustomSeries', renderItem));
 * chart.setOption({
 *     series: [{
 *         type: 'myCustomSeries',
 *         // Reusable payload, retrieved by `params.itemPayload` in `renderItem`.
 *         itemPayload: { someProp: 123 },
 *         data: [ ... ]
 *     }]
 * });
 * ```
 *
 * `renderItem` can still be overridden in the series option if needed.
 */
export function createCustomSeriesInstaller<TItemPayload = unknown>(
    seriesType: string,
    renderItem: CustomSeriesRenderItem<TItemPayload>
): EChartsExtensionInstaller {
    if (__DEV__) {
        assert(isString(seriesType) && !!seriesType, 'seriesType should be a non-empty string.');
        assert(isFunction(renderItem), 'renderItem should be a function.');
    }

    const seriesFullType = 'series.' + seriesType;

    class ReusableCustomSeriesModel extends CustomSeriesModel {
        static type = seriesFullType;
        readonly type = seriesFullType;

        // Notice: `getDefaultOption` does not travel the class hierarchy for
        // classes declared by the `class` syntax, so merge it manually.
        static defaultOption: CustomSeriesOption<TItemPayload> = defaults(
            { renderItem: renderItem } as CustomSeriesOption<TItemPayload>,
            CustomSeriesModel.defaultOption as CustomSeriesOption<TItemPayload>
        );
    }

    class ReusableCustomChartView extends CustomChartView {
        static type = seriesType;
        readonly type = seriesType;
    }

    return function (registers: EChartsExtensionInstallRegisters) {
        registers.registerSeriesModel(ReusableCustomSeriesModel);
        registers.registerChartView(ReusableCustomChartView);
    };
}

/**
 * Register a reusable custom series as a new series type. It is a shortcut of
 * `use(createCustomSeriesInstaller(seriesType, renderItem))`.
 *
 * @see createCustomSeriesInstaller
 */
export function registerCustomSeries<TItemPayload = unknown>(
    seriesType: string,
    renderItem: CustomSeriesRenderItem<TItemPayload>
): void {
    use(createCustomSeriesInstaller(seriesType, renderItem));
}

